package android.content;import android.os.Bundle;public class Intent{private String action;private Bundle extras;public Intent(){}public Intent(Context context,Class<?> target){}public Intent setAction(String action){this.action=action;return this;}public String getAction(){return action;}public Bundle getExtras(){return extras;}public Intent putExtra(String key,String value){if(extras==null)extras=new Bundle();extras.putString(key,value);return this;}public Intent putExtra(String key,long value){if(extras==null)extras=new Bundle();extras.putLong(key,value);return this;}public void removeExtra(String key){if(extras!=null)extras.remove(key);}}
